public enum PizzaSize {
    REGULAR("Regular", 381.00),
    LARGE("Large", 602.00),
    PARTY("Party", 799.00);

    private final String label;
    private final double price;

    PizzaSize(String label, double price) {   // enum constructors are always private
        this.label = label;
        this.price = price;
    }

    public String getLabel() { return label; }
    public double getPrice() { return price; }

    public double priceWithVat() { return price * 1.12; }
}

public class Menu {
    public static void main(String[] args) {
        for (PizzaSize size : PizzaSize.values()) {
            System.out.printf("%-8s %8.2f  (with VAT %8.2f)%n",
                              size.getLabel(), size.getPrice(), size.priceWithVat());
        }
    }
}
